/**
 * Unit tests for the protected method doOptimize in BrentOptimizer.
 * Since doOptimize is protected and currently throws UnsupportedOperationException,
 * we use reflection to access it for testing purposes.
 */
public class BrentOptimizer_doOptimize_TriageGen1Test {

    private BrentOptimizer optimizer;
    private Method doOptimizeMethod;

    @Before
    public void setUp() throws NoSuchMethodException {
        optimizer = new BrentOptimizer();
        doOptimizeMethod = BrentOptimizer.class.getDeclaredMethod("doOptimize");
        doOptimizeMethod.setAccessible(true);
    }

    @Test
    public void testDoOptimizeThrowsUnsupportedOperationException() throws Throwable {
        try {
            doOptimizeMethod.invoke(optimizer);
            fail("Expected UnsupportedOperationException to be thrown");
        } catch (java.lang.reflect.InvocationTargetException e) {
            if (!(e.getTargetException() instanceof UnsupportedOperationException)) {
                fail("Expected UnsupportedOperationException, but got: " + e.getTargetException().getClass().getName());
            }
        }
    }

    /**
     * Note: In the provided source code, doOptimize() always throws UnsupportedOperationException.
     * Therefore, branch coverage for the logic inside the method (if any existed) is impossible
     * to reach beyond the throw statement. This test ensures the current implementation 
     * behavior is captured.
